questionvariables.text:
mlist : [[2,1],[3,2],[4,1],[4,3]];
cands : [];
for mn in mlist do
  for kk : 1 thru 5 do (
    l1 : kk*(mn[1]^2 - mn[2]^2),
    l2 : kk*(2*mn[1]*mn[2]),
    hh : kk*(mn[1]^2 + mn[2]^2),
    if max(l1, l2, hh) <= 30
      then cands : endcons([max(l1,l2), min(l1,l2), hh], cands)
  );
pick : rand(cands);
lega : pick[1];                 /* longer leg  (horizontal) */
legb : pick[2];                 /* shorter leg (vertical)   */
hyp  : pick[3];                 /* hypotenuse (a whole number, NOT shown) */
ta1  : hyp/2;                   /* model answer: circumradius = half the hypotenuse */
wrong_hyp : hyp;               /* gave the hypotenuse = diameter, forgot to halve */
wrong_addlegs : (lega+legb)/2; /* used hypotenuse = lega+legb instead of Pythagoras */
